            var ptr   = Marshal.AllocHGlobal(bytes.Length);
            try   { Marshal.Copy(bytes, 0, ptr, bytes.Length); return wdmm_proxy_hls_seek(ptr, offsetSecs).ToStringAndFree(); }
            finally { Marshal.FreeHGlobal(ptr); }
        }

